// The achievement id mapping for platform services. The game's ids (src/game/achievements.ts, ACHIEVEMENTS[].id) are stable
// snake_case and never change once shipped; each service may want its own names:
//  - Steam: the API name in the Steamworks partner site. Use the game's id as the API name and leave STEAM empty (identity);
//    list a pair here only where an API name had to differ.
//  - Google Play Games: ids are generated by the Play Console ('CgkI...'); paste them here after creating the achievements.
//    An achievement without an entry is skipped on Play (the game still records it).
export const STEAM_IDS: Readonly<Record<string, string>> = {};
export const PLAY_IDS: Readonly<Record<string, string>> = {};

/** The service's name for a game achievement id, or null when the service has none for it. */
export function platformAchId(service: 'steam' | 'play', id: string): string | null {
  if (service === 'steam') return Object.hasOwn(STEAM_IDS, id) ? STEAM_IDS[id] : id;
  return Object.hasOwn(PLAY_IDS, id) ? PLAY_IDS[id] : null;
}
